# PLAN (combat-micro first, one champion's view):
# - Draft the strong ladder five (Heart of Ruin, Vesper Vale, Vendetta, Marcella, Ryth).
# - Turn order: healthier champions act first (set_priority = hp%), so the fresh one lands
#   the first hit and the wounded one acts after the enemy has committed.
# - Fight only when an enemy is within 4. Focus the team target if it is close,
#   otherwise the nearest enemy, and publish it so allies hit the same unit on the same turn.
# - Micro sequence: stun opener (dash or cast) -> close the gap (non-stun dash for melee)
#   -> basic attack -> self-cast reset after the basic -> attack again -> damage/AoE
#   ability -> shield/heal. Ranged: attack from range 3; step away from an adjacent enemy
#   only when hurt (kite), otherwise trade.
# - Retreat when low and outnumbered; recall only when not in danger; heal on spawn.
# - Wards: drop one at the altar while tributing, and into a nearby bush while
#   clearing camps, so ambushes are seen before they land the first hit.
# - Farm: finish captures, hit camps in range, walk to the nearest camp, but prefer a
#   rich (15+ gem) group if it is only a few tiles farther. Avoid monolith groups/altars.

keep RETREAT_HP = 0.3
keep RECALL_HP = 0.4
keep KITE_HP = 0.5
keep BAG = 30
keep RICH_EXTRA = 6

def hpf():
    return health() / max_health()

def dist_to(u):
    return distance(position(), unit_position(u))

def fight(t):
    if ability_ready(1) and slot_stun(1) > 0 and dist_to(t) <= slot_range(1) + slot_radius(1):
        if slot_is_dash(1):
            dash_towards(1, unit_position(t))
        else:
            cast_at_unit(1, t)
    elif ability_ready(0) and slot_stun(0) > 0 and dist_to(t) <= slot_range(0) + slot_radius(0):
        if slot_is_dash(0):
            dash_towards(0, unit_position(t))
        else:
            cast_at_unit(0, t)
    if i_am_ranged():
        if dist_to(t) <= 1 and hpf() < KITE_HP:
            move_away_from(unit_position(t))
        elif dist_to(t) <= 3:
            attack(t)
        else:
            move_towards(unit_position(t))
    else:
        if dist_to(t) > 1:
            if ability_ready(0) and slot_is_dash(0) and slot_stun(0) == 0 and dist_to(t) <= 3:
                dash_towards(0, unit_position(t))
            elif ability_ready(1) and slot_is_dash(1) and slot_stun(1) == 0 and dist_to(t) <= 3:
                dash_towards(1, unit_position(t))
            move_towards(unit_position(t))
        attack(t)
    if not can_attack() and dist_to(t) <= 3:
        if ability_ready(0) and slot_is_reset(0):
            cast_self(0)
            attack(t)
        elif ability_ready(1) and slot_is_reset(1):
            cast_self(1)
            attack(t)
    if ability_ready(0) and (slot_is_damage(0) or slot_is_aoe(0)) and slot_stun(0) == 0 and dist_to(t) <= slot_range(0) + slot_radius(0):
        cast_at_unit(0, t)
    elif ability_ready(1) and (slot_is_damage(1) or slot_is_aoe(1)) and slot_stun(1) == 0 and dist_to(t) <= slot_range(1) + slot_radius(1):
        cast_at_unit(1, t)
    elif ability_ready(0) and slot_is_shield(0):
        cast_self(0)
    elif ability_ready(1) and slot_is_shield(1):
        cast_self(1)
    elif ability_ready(0) and slot_is_heal(0) and hpf() < 0.7:
        cast_self(0)
    elif ability_ready(1) and slot_is_heal(1) and hpf() < 0.7:
        cast_self(1)

def go_tribute(a):
    if distance(position(), a) <= 1:
        tribute(a)
        place_ward(position())
    else:
        move_towards(a)

if is_draft():
    let pool = unpicked_champions()
